import pyomo.environ as pyo

DATA = {
    "cities": ["E", "F", "G", "H", "I"],
    "cost": {
        ("E", "F"): 31, ("E", "G"): 19, ("E", "H"): 71, ("E", "I"): 74,
        ("F", "E"): 31, ("F", "G"): 39, ("F", "H"): 77, ("F", "I"): 84,
        ("G", "E"): 19, ("G", "F"): 39, ("G", "H"): 65, ("G", "I"): 78,
        ("H", "E"): 71, ("H", "F"): 77, ("H", "G"): 65, ("H", "I"): 38,
        ("I", "E"): 74, ("I", "F"): 84, ("I", "G"): 78, ("I", "H"): 38,
    },
    "num_cities": 5,
    "big_m": 1000,
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    cities = d["cities"]
    cost = d["cost"]
    n = d["num_cities"]
    big_m = n

    model = pyo.ConcreteModel()

    model.N = pyo.Set(initialize=cities)
    model.A = pyo.Set(initialize=[(i, j) for i in cities for j in cities if i != j], dimen=2)

    model.x = pyo.Var(model.A, within=pyo.Binary)
    model.u = pyo.Var(model.N, within=pyo.NonNegativeReals, bounds=(1, n))

    def obj_rule(m):
        return sum(cost[(i, j)] * m.x[i, j] for (i, j) in m.A)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def out_rule(m, i):
        return sum(m.x[i, j] for j in cities if j != i) == 1

    model.out_arc = pyo.Constraint(model.N, rule=out_rule)

    def in_rule(m, j):
        return sum(m.x[i, j] for i in cities if i != j) == 1

    model.in_arc = pyo.Constraint(model.N, rule=in_rule)

    def mtz_rule(m, i, j):
        if i == j:
            return pyo.Constraint.Skip
        return m.u[j] >= m.u[i] + 1 - big_m * (1 - m.x[i, j])

    model.mtz = pyo.Constraint(model.N, model.N, rule=mtz_rule)

    return model
